'use client';
import {useState,useEffect,useRef} from 'react';
import {selectRoomIds} from '@/lib/room-selection';
import {dailyOpsSummary,dailyOpsSummaryRows} from '@/lib/daily-ops-summary';
import {downloadReport} from '@/lib/report-export';
import type {HotelWorkspace,Room} from '@/lib/pilot';
export function TodayRoomBoard({workspace,onRoom,renderActions,renderBulkActions,disabled=false,id='today-room-board'}:{workspace:HotelWorkspace;onRoom?:(room:Room)=>void;renderActions?:(room:Room)=>React.ReactNode;renderBulkActions?:(rooms:Room[])=>React.ReactNode;disabled?:boolean;id?:string}){
 const [selectedIds,setSelectedIds]=useState<string[]>([]);const anchor=useRef<string|null>(null);
 const selected=workspace.rooms.filter(r=>selectedIds.includes(r.id));const selectedRoom=selected.length===1?selected[0].id:null;
 const actionsRef=useRef<HTMLElement>(null);useEffect(()=>{if(selectedIds.length===1)actionsRef.current?.scrollIntoView({behavior:'smooth',block:'nearest'})},[selectedIds]);
 const [query,setQuery]=useState(''),[filter,setFilter]=useState('All'),[reportError,setReportError]=useState('');
 const stays=workspace.reservations.filter(r=>r.status==='In house');
 const maintenanceNow=(room:Room)=>room.maintenance_intervals?.some(m=>m.start<=workspace.business_date&&m.end>workspace.business_date);
 const isReady=(room:Room)=>room.status==='Clean'&&!room.open_turnover_task&&!maintenanceNow(room)&&!stays.some(s=>s.physical_room_id===room.id);
 const summary=dailyOpsSummary(workspace);
 const totals=[['Ready rooms',summary.readyRooms],['In house',summary.inHouse],['Arrivals today',summary.arrivals],['Departures today',summary.departures],['Rooms to prepare',summary.roomsToPrepare]] as const;
 const visible=workspace.rooms.filter(room=>{const occupied=stays.some(s=>s.physical_room_id===room.id);const ready=isReady(room);const text=[room.label,workspace.room_types.find(t=>t.id===room.room_type_id)?.name,stays.find(s=>s.physical_room_id===room.id)?.guest_name].join(' ').toLowerCase();return text.includes(query.trim().toLowerCase())&&(filter==='All'||filter==='Clean'&&room.status==='Clean'||filter==='Dirty'&&room.status==='Dirty'||filter==='Maintenance'&&!!maintenanceNow(room)||filter==='In house'&&occupied||filter==='Ready'&&ready||filter==='To prepare'&&(room.status!=='Clean'||!!room.open_turnover_task))});
 const ordered=[...visible].sort((a,b)=>a.label.localeCompare(b.label,undefined,{numeric:true}));
 function choose(id:string,range=false,toggle=false){if(disabled)return;setSelectedIds(current=>selectRoomIds(current,anchor.current,id,ordered.map(r=>r.id),range,toggle));if(!range)anchor.current=id;}
 function clear(){setSelectedIds([]);anchor.current=null;}
 return <div id={id} className="today-room-layout"><section className="card today-all-rooms" aria-labelledby="today-rooms-title"><div className="section-top"><h2 id="today-rooms-title">All rooms</h2><span className="count">{workspace.rooms.length}</span></div><div className="section-top"><div><strong>Daily operations brief</strong><p>{summary.property} · {summary.businessDate} · {summary.timeZone}</p></div><button type="button" className="secondary" disabled={disabled} onClick={()=>{try{downloadReport("iRatePilot-daily-brief-"+summary.businessDate,dailyOpsSummaryRows(summary));setReportError("")}catch{setReportError("The daily brief could not be downloaded. Refresh workspace and try again.")}}}>Download daily brief CSV</button></div>{reportError&&<p className="pilot-error" role="alert">{reportError}</p>}<div className="room-board-controls"><label className="field">Find a room or guest<input type="search" value={query} placeholder="Room number, type or guest" disabled={disabled} onChange={e=>{clear();setQuery(e.target.value)}}/></label><fieldset className="room-board-filters" aria-label="Filter rooms">{['All','Ready','In house','To prepare','Clean','Dirty','Maintenance'].map(value=><button type="button" key={value} aria-pressed={filter===value} disabled={disabled} onClick={()=>{clear();setFilter(value)}}>{value}</button>)}</fieldset><p aria-live="polite">{visible.length} of {workspace.rooms.length} rooms</p></div><p>Click a room, then Shift-click another to select a range. Use checkboxes or Ctrl/Cmd-click for individual rooms.</p>{selected.length>1&&<section className="card" aria-label="Selected rooms actions"><div className="section-top"><h3>{selected.length} rooms selected</h3><button type="button" disabled={disabled} onClick={clear}>Clear selection</button></div>{renderBulkActions?.(selected)}</section>}{selectedRoom&&workspace.rooms.some(r=>r.id===selectedRoom)&&<section ref={actionsRef} className="card" aria-label="Selected room actions"><div className="section-top"><h3>Room {workspace.rooms.find(r=>r.id===selectedRoom)!.label}</h3><button type="button" disabled={disabled} onClick={clear}>Close</button></div>{renderActions?.(workspace.rooms.find(r=>r.id===selectedRoom)!)}<button className="secondary" type="button" disabled={disabled} onClick={()=>onRoom?.(workspace.rooms.find(r=>r.id===selectedRoom)!)}>{stays.some(s=>s.physical_room_id===selectedRoom)?"Manage stay":"Walk-in / Check-in"}</button></section>}<div className="today-room-board">{ordered.map(room=>{const stay=stays.find(s=>s.physical_room_id===room.id);const maintenance=maintenanceNow(room);return <article className={'today-room-tile '+(stay?'occupied':maintenance?'maintenance':room.status==='Clean'&&!room.open_turnover_task?'ready':'prepare')} key={room.id} style={selectedIds.includes(room.id)?{outline:"3px solid #365fe9",outlineOffset:2}:undefined}><label style={{display:"flex",gap:8,alignItems:"center"}}><input type="checkbox" aria-label={"Select room "+room.label} checked={selectedIds.includes(room.id)} disabled={disabled} onChange={()=>choose(room.id,false,true)}/>Select</label><button type="button" className="today-room-number text-button" aria-label={'Room '+room.label+' — select room actions'} disabled={disabled} onClick={e=>choose(room.id,e.shiftKey,e.ctrlKey||e.metaKey)}>{room.label}</button><div className="today-room-type">{workspace.room_types.find(t=>t.id===room.room_type_id)?.name??'Room'}</div><span className="today-room-occupancy">{stay?'In house':'Vacant'}</span><span className="today-room-condition">{room.status}{maintenance?' · Maintenance':''}{room.open_turnover_task?' · Turnover':''}</span>{stay&&<small>{stay.guest_name||'In-house guest'}</small>}</article>})}</div>{!!workspace.rooms.length&&!visible.length&&<p className="pilot-empty">No rooms match. Try another search or select All.</p>}{!workspace.rooms.length&&<p className="pilot-empty">Add rooms in Property settings to see them here.</p>}</section><aside className="today-summary" aria-label="Today’s room summary">{totals.map(([label,count])=><section className="card" key={label}><span>{label}</span><strong>{count}</strong></section>)}</aside></div>;
}
